 vocab=[('gesture','a movement of part of your body to show what you mean or feel'),('body language','the way we move our bodies, make gestures or use facial expressions to send a message'),('facial expression','a look on your face that shows how you feel'),('signal','a sign or action that gives information'),('eye contact','looking directly into another person\'s eyes'),('confident','sure that you can do something well'),('trustworthy','able to be trusted'),('liar','someone who says things that are not true')],
